-- ============================================================
-- SEED EXT 5: Módulo 13 — Reported Speech (ex 211-300) — FINAL
-- Consolidação: RS em TOEFL avançado, reporting em academic writing,
-- RS com todas as estruturas de mudança de forma
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'reported-speech';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo reported-speech não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 51: Reporting avançado em academic writing
  (cid,51,211,'multiple_choice','In academic writing, "Smith (2020) argues that inequality has structural causes." Why no backshift?','Academic writing conventionally uses present tense to report still-valid arguments.','["Smith is still alive","Past tense is too informal","Academic writing conventionally uses present tense to report still-valid arguments.","All academic reporting uses past"]','Academic present: argues/shows/demonstrates/suggests = reporting still-relevant claims.','easy'),
  (cid,51,212,'gap_fill','Jones _____ (argue) that the current model _____ (fail) to account for long-term demographic shifts; however, subsequent research _____ (challenge) this position.','argues / fails / has challenged',NULL,'Academic present for Jones''s ongoing argument + PP for subsequent challenges.','medium'),
  (cid,51,213,'gap_fill','The professor explained that the economy _____ (grow) in the 1990s but _____ (slow) significantly after the 2000 technology crash.','had grown / had slowed',NULL,'Backshift in personal reported speech: grew → had grown, slowed → had slowed.','medium'),
  (cid,51,214,'multiple_choice','Which academic reporting verb expresses DISAGREEMENT with a prior claim?','Chen (2022) disputes that automation has been the primary driver of wage stagnation.','["Chen (2022) confirms that automation has been the primary driver.","Chen (2022) disputes that automation has been the primary driver of wage stagnation.","Chen (2022) demonstrates that automation has been the primary driver.","Chen (2022) argues that automation has been the primary driver."]','"Disputes" = reporting verb for disagreement. "Confirms/demonstrates/argues" = neutral or agreeing.','medium'),
  (cid,51,215,'gap_fill','The WHO _____ (warn) that antibiotic resistance _____ (be) one of the greatest health threats, while the report _____ (urge) governments _____ (take) immediate action.','warned / was / urged / to take',NULL,'Past RS: warned (that) + was (backshift) + urged + to-infinitive.','hard'),

  -- BLOCK 52: RS com pronomes e dêiticos
  (cid,52,216,'gap_fill','Direct: "We have been working on this problem for three years." → Reported: The team said they _____ (work) on that problem for three years.','had been working',NULL,'Backshift: have been working → had been working; we → they; this → that.','medium'),
  (cid,52,217,'gap_fill','Direct: "The results will be published here next week." → Reported: She said the results _____ (publish/passive) there the following week.','would be published',NULL,'Backshift: will → would; active → passive maintained; here → there; next week → the following week.','hard'),
  (cid,52,218,'multiple_choice','Which sentence correctly shifts ALL deictic elements in reported speech?','He said that he had submitted his thesis the previous day and would defend it the following week.','["He said that I submitted my thesis yesterday and will defend it next week.","He said that he had submitted his thesis the previous day and would defend it the following week.","He said that he submitted his thesis yesterday and would defend it the following week.","He said that he had submitted his thesis yesterday and will defend it next week."]','All changes: I→he, submitted→had submitted, yesterday→the previous day, will→would, next week→the following week.','hard'),
  (cid,52,219,'gap_fill','Direct: "These documents were classified here two years ago." → Reported: Officials confirmed that those documents _____ (classify/passive) there two years _____.','had been classified / earlier / previously / before',NULL,'Backshift: were classified → had been classified; these → those; here → there; ago → before/earlier.','hard'),

  -- BLOCK 53: Perguntas indiretas avançadas
  (cid,53,220,'gap_fill','Direct: "Did the government know about the risks before the decision was made?" → Reported: The journalist asked _____ the government _____ (know) about the risks before the decision _____ (make/passive).','whether / had known / had been made',NULL,'Indirect yes/no question: whether + PS word order + backshift.','hard'),
  (cid,53,221,'gap_fill','Direct: "Which model best explains the distribution of outcomes?" → Reported: Researchers were investigating _____ model _____ (best/explain) the distribution of outcomes.','which / best explained',NULL,'Indirect WH question: which + subject + verb (backshift).','medium'),
  (cid,53,222,'multiple_choice','Which indirect question is CORRECTLY formed?','The committee wanted to know how the funds had been allocated.','["The committee wanted to know how had the funds been allocated.","The committee wanted to know how the funds had been allocated.","The committee wanted to know how the funds have been allocated.","The committee wanted to know how were the funds allocated."]','Indirect question: statement word order + backshift (were allocated → had been allocated).','medium'),
  (cid,53,223,'gap_fill','The auditors _____ (ask) why the discrepancy _____ (not/report/passive) earlier and _____ (want) to know _____ the original data _____ (still/be) available.','asked / had not been reported / wanted / whether / was still',NULL,'Two indirect questions: why + PP passive + whether + PS.','hard'),

  -- BLOCK 54: Verbos de reporte avançados (padrões V+obj+inf)
  (cid,54,224,'gap_fill','The supervisor _____ (remind) the team _____ (submit) their progress reports by Friday.','reminded / to submit',NULL,'"Remind + obj + to + base verb" = V+obj+inf pattern.','easy'),
  (cid,54,225,'gap_fill','The regulator _____ (order) the company _____ (cease) operations immediately and _____ (provide) full disclosure of its financial position.','ordered / to cease / to provide',NULL,'"Order + obj + to + base verb" pattern x2.','easy'),
  (cid,54,226,'multiple_choice','Which reporting verb pattern is CORRECTLY used?','"The board authorized the committee to proceed with the investigation."','["The board authorized that the committee proceeds with the investigation.","The board authorized the committee to proceed with the investigation.","The board authorized the committee proceed with the investigation.","The board authorized that the committee to proceed with the investigation."]','"Authorize + obj + to + base verb" = V+obj+inf pattern.','medium'),
  (cid,54,227,'gap_fill','The UN _____ (call on) member states _____ (increase) contributions and _____ (urge) the Security Council _____ (convene) an emergency session.','called on / to increase / urged / to convene',NULL,'"Call on + obj + to inf" + "urge + obj + to inf" = formal reporting patterns.','hard'),
  (cid,54,228,'gap_fill','The treaty _____ (oblige) signatories _____ (report) annually and _____ (allow) international observers _____ (inspect) facilities.','obliges / to report / allows / to inspect',NULL,'"Oblige + obj + to inf" + "allow + obj + to inf" = V+obj+inf formal patterns.','medium'),

  -- BLOCK 55: TOEFL Reading
  (cid,55,229,'multiple_choice','[TOEFL Reading] In academic texts, reporting verbs like "maintains," "argues," and "suggests" are in the present tense because:','They attribute a still-current position to the cited author.','["The work was recently published","They attribute a still-current position to the cited author.","Present tense is more formal","They describe ongoing experiments"]','Academic present reporting: the author''s position remains in their published work.','easy'),
  (cid,55,230,'gap_fill','[TOEFL Reading] "Critics _____ (contend) that the model _____ (underestimate) the role of behavioral factors, while proponents _____ (maintain) that it _____ (capture) the most empirically significant variables." Best forms?','contend / underestimates / maintain / captures',NULL,'Academic RS: present tense for ongoing theoretical debate.','medium'),
  (cid,55,231,'multiple_choice','[TOEFL Reading] "The authors note that their findings could not be generalized beyond the specific cultural context studied." The backshift "could" (from "can") was applied because:','The noting is past — it occurred in the original text (past publication context).','["Could is more formal","The findings are not certain","The noting is past — it occurred in the original text (past publication context).","Academic writing always uses could"]','When we say "the authors noted" (past), backshift applies: can → could.','hard'),

  -- BLOCK 56: TOEFL Speaking
  (cid,56,232,'production','[TOEFL Speaking — 45s] Summarize a reading on artificial intelligence governance. The reading argues that self-regulation will not work. Use academic RS throughout.','',NULL,'The reading contends that voluntary self-regulation by artificial intelligence companies cannot adequately protect the public from the risks these systems pose. The authors argue that self-regulatory frameworks have systematically failed in analogous industries — financial services, social media — where the costs of harmful behavior were diffuse and the benefits of insufficient oversight were concentrated in corporate profits. The reading maintains that independent public oversight bodies should be established with the authority to require pre-deployment safety testing, demand algorithmic transparency, and impose meaningful penalties for violations. It further claims that international coordination is essential, since a regulatory race to the bottom would undermine any jurisdiction-level framework. Crucially, the reading suggests that the technology is developing too rapidly for reactive regulation to work, and that proactive standards must be established now rather than after significant harm has already occurred.','hard'),
  (cid,56,233,'production','[TOEFL Speaking — 45s] Report what a professor argued in a lecture about urban planning. Use backshift, reporting verbs, and indirect speech.','',NULL,'In the lecture, the professor argued that conventional urban planning had prioritized the needs of commuters over the needs of residents, producing cities that were efficient transit corridors but poor living environments. She claimed that the mid-twentieth century was the period when American cities most aggressively restructured their urban cores to accommodate the automobile, and she suggested that many of the social pathologies associated with urban poverty — social isolation, reduced physical activity, community fragmentation — could be traced to planning decisions made in that era. The professor noted that researchers who had studied the relationship between urban form and human well-being had consistently found that walkable, mixed-use neighborhoods were associated with better health outcomes and stronger social capital than car-dependent suburbs. She recommended that students read Jane Jacobs''s critique of urban renewal, insisting that it remained one of the most insightful analyses of how city environments affect human behavior.','hard'),

  -- BLOCK 57: Estruturas avançadas — RS em TOEFL Writing
  (cid,57,234,'production','[TOEFL Writing — 200 words] Write a paragraph summarizing and analyzing two opposing views from academic sources. Use academic reporting verbs (present tense) and contrasting discourse markers.','',NULL,'Scholars are sharply divided on the question of whether economic globalization has contributed to or ameliorated global inequality. On one side, Milanovic (2016) argues that globalization has, on balance, reduced inequality between countries by enabling convergence in incomes between wealthy and developing nations, particularly in East and South Asia. He maintains that the spectacular growth of China and India, which lifted hundreds of millions of people out of extreme poverty, represents a dramatic reduction in global inequality by any population-weighted measure. By contrast, Rodrik (2011) contends that the distributional consequences of globalization are far more mixed than aggregate statistics suggest. He claims that trade liberalization has hollowed out middle-income jobs in advanced economies while disproportionately benefiting the very rich, producing a polarization of incomes that aggregate growth figures conceal. Furthermore, Rodrik maintains that the pace and manner of integration matters as much as integration itself, noting that countries that managed their insertion into the global economy carefully — as East Asian developmental states did — fared considerably better than those that liberalized rapidly in response to external pressure.','hard'),
  (cid,57,235,'production','[TOEFL Writing — 200 words] Write a body paragraph reporting the findings of studies on online learning. Use a variety of academic reporting verbs.','',NULL,'The research literature on online learning effectiveness presents a nuanced and sometimes contradictory picture. Means et al. (2013) demonstrate, in one of the most comprehensive meta-analyses to date, that students in online environments perform modestly better than those in traditional face-to-face settings on average, a finding that the authors attribute partly to the greater amount of time students spend engaged with course material in self-paced digital formats. Conversely, Xu and Jaggars (2014) find in their study of community college students that online courses produce significantly lower completion rates and grade outcomes, particularly among academically underprepared and lower-income students, suggesting that the average positive effect masks substantial heterogeneity across student populations. Researchers in the field tend to agree that the quality of instructional design matters more than the delivery modality itself, and several studies suggest that the benefits of online learning accrue primarily to motivated, well-prepared students who require flexibility of scheduling. The literature does not support the claim that online instruction represents a uniformly superior or inferior mode of learning; rather, it indicates that the match between student characteristics, course design, and learning goals determines outcomes more than the presence or absence of physical classroom space.','hard'),

  -- BLOCK 58: Final exercícios 236-300
  (cid,58,236,'gap_fill','The scientist _____ (note) that the original data _____ (not/verify/passive) and _____ (urge) colleagues _____ (conduct) an independent audit before the findings _____ (publish/passive).','noted / had not been verified / urged / to conduct / were published',NULL,'RS sequence: noted + PP passive + urged + to inf + PS passive.','hard'),
  (cid,58,237,'production','[TOEFL Writing — 200 words] Write a paragraph on climate policy debates. Report the positions of at least three scholars or institutions using a variety of reporting verbs and tenses.','',NULL,'The political economy of climate change has generated one of the most contested bodies of scholarship in contemporary social science. The Intergovernmental Panel on Climate Change consistently reports that rapid and far-reaching transitions in energy, land use, transport, and industry are required to limit warming to 1.5°C above pre-industrial levels, maintaining that the costs of inaction substantially exceed the costs of mitigation. Nordhaus (2018) argues for a more gradual approach, contending that an optimal carbon price determined by economic modeling should be allowed to guide the transition rather than regulatory mandates that distort market signals. Critics such as Keen (2021) dispute this framework, claiming that it systematically underestimates the severity of climate damages by failing to model non-linear tipping point dynamics. Jacobs (2012) suggests that effective climate policy requires not just carbon pricing but active industrial policy to direct investment toward low-carbon alternatives that markets will not spontaneously develop, given the pervasive market failures in innovation and infrastructure. Meanwhile, Sovacool et al. (2022) insist that social and behavioral dimensions of the transition have been neglected in economics-dominated policy analysis, noting that technological solutions alone will not produce the required emissions reductions without complementary changes in how people travel, eat, and heat their homes.','hard'),
  (cid,58,238,'production','[TOEFL Speaking — 60s] Report what you have read about the relationship between inequality and democracy. Use academic reporting verbs throughout.','',NULL,'Scholars working on the relationship between economic inequality and democratic health have reached broadly convergent but nuanced conclusions. Acemoglu and Robinson (2006) argue in their influential account that democracy tends to emerge when economic elites calculate that conceding political rights is preferable to facing revolution, suggesting that the relationship is shaped by distributional conflict. Putnam (2015) demonstrates empirically that rising income inequality in the United States has been associated with declining civic participation and social trust among lower-income groups, maintaining that extreme inequality corrodes the social infrastructure that democracy requires to function. Gilens (2012) finds that policy outcomes in the United States correlate strongly with the preferences of economic elites and weakly with the preferences of ordinary citizens, claiming that American democracy has become systematically more responsive to the wealthy. By contrast, some comparative political scientists suggest that the relationship between inequality and democratic erosion is not deterministic, noting that Nordic countries have maintained strong democratic institutions despite being highly exposed to economic globalization. The weight of the evidence, however, indicates that inequality at the levels now observed in several advanced democracies poses a genuine challenge to political equality, even where formal democratic institutions remain intact.','hard'),
  (cid,58,239,'production','[TOEFL Writing — 200 words] Write a conclusion for a TOEFL essay on whether technology improves governance. Use RS to summarize arguments and present your own position.','',NULL,'This essay has examined the claim that technology enhances governance and found that the relationship is substantially more conditional than either optimistic or pessimistic accounts suggest. As scholars such as Noveck (2015) argue, digital platforms do offer genuine tools for civic engagement, transparency, and participatory policymaking that have been successfully deployed in several jurisdictions. Equally, as Morozov (2013) contends, technology can serve authoritarian as well as democratic purposes, and the same surveillance infrastructure that enables targeted public services also enables targeted repression. The evidence suggests, as this essay has argued, that technology is best understood as an amplifier of existing institutional conditions rather than an independent driver of good or bad governance. In contexts where democratic norms, rule of law, and accountability mechanisms are already strong, digital tools tend to enhance their effectiveness. In contexts where these preconditions are weak or absent, the same tools tend to strengthen the capacity of power to entrench itself. Technology reform therefore cannot substitute for institutional reform; it can only enhance it. Governance requires political will, legitimate institutions, and a culture of public accountability — and these are ultimately non-technological achievements that no application can manufacture.','hard'),
  (cid,58,240,'production','[TOEFL Speaking — 60s] Summarize what researchers argue about the benefits and risks of genetic engineering in agriculture. Use a full range of RS structures.','',NULL,'Research on agricultural genetic engineering presents a complex picture in which significant potential benefits are accompanied by genuine and contested risks. Proponents of genetically modified organisms, including researchers associated with the International Food Policy Research Institute, argue that GM crops have increased yields, reduced pesticide use in several major applications, and provided nutritional enhancements — notably vitamin-A-enriched Golden Rice — that could address micronutrient deficiencies in low-income populations. They claim that the scientific consensus on the safety of approved GM foods for human consumption is clear and that opposition to biotechnology in agriculture has cost lives by delaying the adoption of crops that could reduce hunger. Critics, however, contend that the long-term ecological consequences of releasing novel genetic material into agricultural ecosystems are inadequately understood, noting that gene flow to wild relatives of cultivated plants has been documented and that the effects on biodiversity and non-target species remain subjects of legitimate scientific concern. Shiva (2016) argues that corporate control of proprietary seed technology has reinforced rather than reduced agricultural inequality, suggesting that the governance of biotechnology serves the interests of large seed companies more than smallholder farmers. Most researchers in the field appear to agree that the technology itself is neither inherently good nor bad, and that the outcomes depend critically on how it is regulated, owned, and deployed.','hard'),
  (cid,58,241,'gap_fill','The commission _____ (conclude) that the accident _____ (cause/passive) by a combination of equipment failure and operator error, and _____ (recommend) that stricter maintenance protocols _____ (implement/passive) across all facilities.','concluded / had been caused / recommended / be implemented',NULL,'RS: concluded + PP passive + recommended + mandative subjunctive passive.','hard'),
  (cid,58,242,'production','[TOEFL Writing — 200 words] Write a body paragraph on urbanization challenges in developing nations. Use RS to cite experts and data alongside your own analysis.','',NULL,'Scholars of urban development consistently note that the rapid growth of cities in the global South represents one of the defining governance challenges of the twenty-first century. As Davis (2006) argues, the expansion of informal settlements — which he characterizes as a "planet of slums" — reflects a fundamental failure of both markets and states to provide urban infrastructure at the scale required by the pace of rural-to-urban migration. UN-Habitat reports that approximately one billion people currently live in informal settlements characterized by inadequate housing, insecure land tenure, and insufficient access to clean water, sanitation, and electricity. Researchers who study urban informality suggest, however, that informal settlements should not be characterized solely as problems: Hernando de Soto (2000) argues that the entrepreneurial energy and accumulated assets of informal city-dwellers represent an enormous "dead capital" that could be mobilized for development if property rights were extended to informal sectors. This analysis has been challenged by scholars who contend that formalization programs have often displaced the very populations they claim to help. What the evidence does seem to establish clearly is that the quality of local governance — its responsiveness to residents, its capacity for infrastructure investment, and its management of land tenure — is a more reliable predictor of urban outcomes than any single policy intervention.','hard'),
  (cid,58,243,'production','[TOEFL Writing — Final 200 words] Write a body paragraph on the ethics of artificial intelligence. Use RS to report academic and institutional positions, plus your own hedged analysis.','',NULL,'The ethics of artificial intelligence deployment has attracted intense academic and policy attention in recent years, generating a body of scholarship that is notable both for its breadth and for its internal disagreements. Several major institutions, including the European Commission and the OECD, contend that AI systems used in high-stakes decisions must be transparent, explainable, and accountable to human oversight — principles that they argue are not merely desirable but necessary conditions for AI governance that respects fundamental rights. Floridi et al. (2018) propose a framework centered on five ethical principles for AI: beneficence, non-maleficence, autonomy, justice, and explicability, insisting that these principles must be operationalized in technical standards rather than remaining at the level of abstract aspiration. Critics such as Whittaker (2021) suggest that high-level ethical frameworks have been adopted by technology companies precisely because they are non-binding and do not constrain business practices, arguing that what the field calls "ethics washing" has substituted voluntary self-commitment for enforceable regulation. This analysis appears persuasive: the history of technology governance suggests that industry self-regulation in the absence of regulatory threat has rarely produced meaningful protection of the public interest. At the same time, premature over-regulation risks constraining innovations whose full benefits are not yet known.','hard'),
  (cid,58,244,'production','[TOEFL Speaking — 60s final] Report and synthesize what two scholars argue about the future of work. One is optimistic, one is pessimistic.','',NULL,'The academic debate about the future of work is structured by a fundamental disagreement between those who find the historical evidence reassuring and those who argue that this time is genuinely different. On the optimistic side, Autor (2015) contends that fears of technological unemployment are typically unfounded when viewed in historical perspective: previous waves of automation have consistently created more jobs than they destroyed, and there is no theoretical reason to believe that this pattern will not continue. He acknowledges that the distribution of gains matters and that transition costs are real, but maintains that aggregate labor demand will remain robust. Frey and Osborne (2013), whose influential study provoked significant debate, take a more alarming view, arguing that approximately 47% of US occupations are at high risk of automation within the next two decades, noting that machine learning capabilities have extended the frontier of automatable tasks well beyond routine physical and cognitive work into creative and interpersonal domains previously thought to be safe. Acemoglu and Restrepo (2020) have since argued that whether automation creates or destroys jobs depends heavily on whether the technologies that replace labor also generate new tasks that require human input, suggesting that current AI development is unusually labor-displacing relative to previous technological waves.','hard'),
  (cid,58,245,'production','[TOEFL Writing — Final production task] Write a 200-word conclusion for a TOEFL essay on ''Is economic growth compatible with environmental sustainability?'' Use RS and academic hedging.','',NULL,'The evidence examined in this essay suggests that the relationship between economic growth and environmental sustainability is neither one of necessary conflict nor of easy compatibility, but of contingent tension that policy can, with difficulty, manage. Scholars such as Daly (1996) argue that conventional economic growth — measured in GDP — is fundamentally incompatible with ecological sustainability because it requires ever-increasing throughput of matter and energy in a finite biosphere. Advocates of green growth, including the OECD and many mainstream economists, contend that decoupling economic value creation from material throughput is achievable at the required scale through technological innovation and appropriate pricing of environmental externalities. The empirical record suggests, as this essay has argued, that partial decoupling has occurred in some high-income economies in some domains, but that absolute decoupling at the global scale required to stabilize the climate and halt biodiversity loss has not been demonstrated at any significant scale. This does not mean that growth and sustainability are permanently incompatible; it does mean that the burden of proof lies with those who claim that a growth-centered development model can, without fundamental changes to its composition and governance, remain within planetary boundaries. What seems increasingly clear is that the question is less whether we can grow and more what we are growing toward.','hard'),
  (cid,58,246,'production','[TOEFL Reading — RS comprehension] "The archaeologist claimed that the artifacts predated any previously known settlement in the region." The original direct speech was:','',NULL,'Original: "These artifacts predate any previously known settlement in the region." OR "These artifacts date to a period before any previously known settlement in the region." → Reported: backshift (predate → predated), the (these → the region = paraphrase). No change to "settlement in the region" since it is a fixed description.','hard'),
  (cid,58,247,'multiple_choice','[Final Review] In TOEFL writing, when should you use PAST reporting verbs vs PRESENT?','Past for time-anchored quotations; present for ongoing scholarly positions.','["Always use past","Always use present","Past for time-anchored quotations; present for ongoing scholarly positions.","Use present only for living scholars"]','Past: "Darwin proposed in 1859 that..." (historical moment). Present: "Darwin argues that..." (textual position remains).','hard'),
  (cid,58,248,'production','[TOEFL Writing — 200 words] Write a paragraph on the public health debate around sugar taxation. Use RS to report the positions of health researchers, economists, and industry.','',NULL,'The proposal to tax sugar-sweetened beverages has generated a substantial debate in which health researchers, economists, and industry representatives have advanced fundamentally different framings of the evidence. Public health researchers consistently argue that excess sugar consumption is causally linked to obesity, type 2 diabetes, and cardiovascular disease, and they maintain that price interventions are among the most cost-effective public health tools available, citing evidence from Mexico, the United Kingdom, and several US cities that beverage taxes have reduced consumption among price-sensitive populations. Behavioral economists suggest that the intervention is justified because individuals systematically underestimate the long-term health consequences of their dietary choices — a cognitive bias that market prices alone cannot correct. The food and beverage industry, unsurprisingly, disputes the evidence for health benefits, claiming that taxes are regressive and that consumers should retain freedom of choice. Several economists note that while the health arguments are compelling, the distributional impact of such taxes does fall disproportionately on lower-income households who spend a higher share of income on food and drink, and they recommend that revenue be recycled to fund health services or subsidize healthier foods to offset the regressive incidence. The debate illustrates how complex the governance of individual health behaviors is when individual choice intersects with social determinants of health.','hard'),
  (cid,58,249,'production','[TOEFL Speaking — 60s] Report the main arguments for and against immigration from a scholarly perspective. Use a range of academic reporting verbs.','',NULL,'The economics of immigration is one of the most heavily researched topics in labor economics, and the scholarly consensus, while not without internal debate, is considerably more positive about immigration''s effects than popular discourse often suggests. Clemens (2011) argues that the removal of immigration restrictions would be one of the largest potential sources of global economic gain available — potentially doubling world GDP — because it allows labor to move from low-productivity to high-productivity environments. Card (1990), in his influential study of the Mariel boatlift, found that the sudden arrival of 125,000 Cuban immigrants in Miami had no discernible negative effect on the wages or employment prospects of existing low-skilled workers, suggesting that labor markets absorb immigration through demand creation rather than displacement. Some economists, including Borjas (2003), dispute this finding, contending that immigration does compete with and reduce wages of similarly skilled native workers, particularly at the lower end of the wage distribution. Researchers who study fiscal effects find that the net impact of immigration on public finances depends heavily on the age composition and skill level of immigrants: working-age skilled migrants typically contribute substantially more in taxes than they consume in services over their lifetimes, while the fiscal impact of family reunification migration and humanitarian admissions is more mixed.','hard'),
  (cid,58,250,'production','[TOEFL Writing — 200 words final] Write a conclusion for a TOEFL essay on ''Should primary schooling focus on academic skills or social-emotional development?'' Report scholars and state your own position.','',NULL,'The dichotomy between academic skill development and social-emotional learning that structures public debate on primary education is, as researchers in developmental psychology consistently argue, largely false in practice. Durlak et al. (2011) demonstrate in a comprehensive meta-analysis that well-designed social-emotional learning programs not only achieve their primary goals but are also positively associated with improvements in academic achievement, suggesting that the two objectives complement rather than compete with each other. Heckman (2006) similarly argues, on the basis of longitudinal data from early childhood intervention programs, that social-emotional competencies — persistence, impulse control, empathy, and cooperation — are at least as predictive of long-term life outcomes as cognitive skills measured by academic tests. This essay has argued, consistent with this evidence, that the framing of a choice between academic and social-emotional priorities reflects a misunderstanding of child development: the brain systems that support learning cannot be meaningfully separated from those that regulate emotion, motivation, and social behavior. A primary education that neglects social-emotional development in the name of academic rigor is not, the evidence suggests, even achieving its own narrow goal effectively, since the capacity to learn depends on affective and interpersonal capacities that must be cultivated, not assumed.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
